"""Test-case traceability at collection (EVOL-053) — the Python home of the case → test link.

The ONE place a test states the case it proves is the `case` marker:

    the `case` marker on the test, with one string argument, e.g. FEAT-001/TC-01:
        def test_database_timeout_returns_503(): ...   (decorated with pytest.mark.case)

Every id is `FEATURE/CASE` — the feature folder under docs/spec/ and the case id its test_plan.md declares (the grammar
is `traceability.id_pattern` in config/quality.json). This plugin refuses collection — never a silent skip — when a
marker carries an id that is malformed or that no plan declares: the declared set is read through the one reader
(`python3 scripts/gate.py traceability --declared --json`), never re-derived here. The push and CI run the same reader
(`gate.py traceability`, a member of the gate profile): every declared case must have a linking test, or sit in the
shrink-only baseline.

Wire it once in tests/conftest.py:   pytest_plugins = ["conftest_traceability"]
(and keep `--strict-markers` in pytest.ini / pyproject: an unregistered marker is a typo, not a link.)
"""
from __future__ import annotations

import json
import subprocess
import sys
from pathlib import Path

import pytest

_DECLARED: set[str] | None = None
_ERROR: str | None = None


def _repo_root(start: Path) -> Path:
    for p in [start, *start.parents]:
        if (p / "scripts" / "gate.py").is_file():
            return p
    return start


def _declared(rootdir: Path) -> set[str]:
    global _DECLARED, _ERROR
    if _DECLARED is not None:
        return _DECLARED
    repo = _repo_root(rootdir)
    try:
        r = subprocess.run([sys.executable, str(repo / "scripts" / "gate.py"), "--repo", str(repo), "traceability", "--declared", "--json"],
                           capture_output=True, text=True, timeout=120)
    except (OSError, subprocess.TimeoutExpired) as e:
        _ERROR = f"the traceability reader could not run: {e}"
        _DECLARED = set()
        return _DECLARED
    if r.returncode != 0:
        _ERROR = (r.stderr.strip().splitlines() or [r.stdout.strip() or "no message"])[-1]
        _DECLARED = set()
        return _DECLARED
    try:
        _DECLARED = set(json.loads(r.stdout).get("declared", []))
    except (ValueError, AttributeError):
        _ERROR = "the traceability reader returned no JSON"
        _DECLARED = set()
    return _DECLARED


def pytest_configure(config):
    config.addinivalue_line("markers", "case(id): the test-plan case this test proves — FEATURE/CASE, e.g. FEAT-001/TC-01 (EVOL-053 traceability home)")


def pytest_collection_modifyitems(config, items):
    problems: list[str] = []
    seen_any = False
    for item in items:
        for m in item.iter_markers(name="case"):
            seen_any = True
            if len(m.args) != 1 or not isinstance(m.args[0], str) or not m.args[0].strip():
                problems.append(f"{item.nodeid}: @pytest.mark.case needs one string id (FEATURE/CASE)")
                continue
            qid = m.args[0].strip()
            declared = _declared(Path(str(config.rootpath)))
            if _ERROR:
                problems.append(f"{item.nodeid}: cannot validate `{qid}` — {_ERROR}")
                continue
            if qid not in declared:
                problems.append(f"{item.nodeid}: `{qid}` names no case any test_plan.md declares (malformed or unknown)")
    if problems:
        raise pytest.UsageError("test-case traceability (EVOL-053): collection refused —\n  " + "\n  ".join(problems))
    if not seen_any:
        return
